cat > /tmp/test-issues.js << 'EOF'
import { upcoming } from './src/renewals.js';
import { monthlyCents } from './src/cycles.js';

// Issue 1 & 2: Check renewals behavior with monthly plan starting Jan 31
const subs = [
  { name: 'Rent', price: 500, cycle: 'monthly', since: '2026-01-31' },
];

console.log('Issue 1&2 test: Monthly plan on Jan 31');
const rows = upcoming(subs, '2027-01-30', 70);
console.log('Renewals within 70 days of 2027-01-30:');
rows.forEach(r => console.log(`  ${r.date}: ${r.name}`));
console.log('Expected: 2027-01-31 only');
console.log('');

// Issue 3: Check total vs list rounding
const subs2 = [
  { name: 'Weekly1', price: 0.01, cycle: 'weekly', since: '2026-01-01' },
  { name: 'Weekly2', price: 0.01, cycle: 'weekly', since: '2026-01-01' },
];

console.log('Issue 3 test: Two weekly plans at €0.01');
const monthly1 = monthlyCents(subs2[0]);
const monthly2 = monthlyCents(subs2[1]);
console.log(`List would show: €${(monthly1 + monthly2).toFixed(2)}`);
const unrounded = 0.01 * (52/12) + 0.01 * (52/12);
const total = Math.round(unrounded);
console.log(`Total would show: €${(total/100).toFixed(2)}`);
console.log('');

// Issue 2 detailed: Wrong dates
console.log('Issue 2 detailed test: Check date sequence');
const subs3 = [
  { name: 'Rent', price: 500, cycle: 'monthly', since: '2026-01-31' },
];
const rows2 = upcoming(subs3, '2027-01-30', 100);
console.log('All renewals within 100 days:');
rows2.forEach(r => console.log(`  ${r.date}`));
console.log('Expected: 2027-01-31, 2027-02-28, 2027-03-31 (but got wrong dates due to addMonths bug)');
EOF
node /tmp/test-issues.js

cat > /tmp/verify-fixes.js << 'EOF'
import { upcoming } from './src/renewals.js';
import { monthlyCents } from './src/cycles.js';

console.log('=== VERIFY FIX 1 & 2: renewals shows next charge only ===');
const subs = [
  { name: 'Rent', price: 50000, cycle: 'monthly', since: '2026-01-31' },
];
const rows = upcoming(subs, '2027-01-30', 100);
console.log(`Monthly plan starting Jan 31, looking within 100 days from Jan 30, 2027:`);
console.log(`Expected: 1 row (2027-01-31)`);
console.log(`Got: ${rows.length} row(s)`);
rows.forEach(r => console.log(`  ${r.date}`));

console.log('\n=== VERIFY FIX 2: Correct dates with monthly plan on 31st ===');
console.log(`Expected dates: 2027-01-31, 2027-02-28, 2027-03-31`);
console.log(`Actually seeing only: ${rows.map(r => r.date).join(', ')}`);

console.log('\n=== VERIFY FIX 3: total matches list (rounding consistency) ===');
const subs2 = [
  { name: 'Weekly1', price: 1, cycle: 'weekly', since: '2026-01-01' },
  { name: 'Weekly2', price: 1, cycle: 'weekly', since: '2026-01-01' },
];
const each = monthlyCents(subs2[0]);
const listTotal = monthlyCents(subs2[0]) + monthlyCents(subs2[1]);
const total = subs2.reduce((sum, s) => sum + monthlyCents(s), 0);
console.log(`Two weekly plans at €0.01 (1 cent) each:`);
console.log(`  list shows: ${each} + ${each} = ${listTotal} cents = €${(listTotal/100).toFixed(2)}`);
console.log(`  total shows: ${total} cents = €${(total/100).toFixed(2)}`);
console.log(`  Match? ${listTotal === total}`);
EOF
node /tmp/verify-fixes.js
